head.script:
// ============================================================
// [XPlatform 원본 스크립트 - 주석으로 보존]
// ============================================================
// 
// function tabMain_canchange(obj:Tab,e:TabIndexChangeEventInfo){ trace("can:"+e.preindex+"->"+e.postindex); return e.postindex != 9; }
// function tabMain_onchanged(obj:Tab,e:TabIndexChangeEventInfo){ trace(e.preindex+"->"+e.postindex); }
// 
// 
// ============================================================

// ============================================================
// [WebSquare 변환 스크립트 - 1차 변환]
// 운영 적용 전에 TODO 표시 항목을 확인하세요.
// ============================================================
var scwin = (typeof scwin === "undefined") ? {} : scwin;

// TODO: WebSquare submission을 구성한 뒤 이 호환 함수를 교체하세요.
scwin.xpTransaction = function() {
    console.warn("[마이그레이션 TODO] XPlatform transaction 호출을 WebSquare submission으로 변환해야 합니다.", arguments);
};


scwin.tabMain_canchange = function(e){ console.log("can:"+e.preindex+"->"+e.postindex); return e.postindex != 9; }
scwin.tabMain_onchanged = function(e){ console.log(e.preindex+"->"+e.postindex); }


// [Phase 3 Tab Event Adapter] XPlatform canchange/onchanged preindex/postindex compatibility
scwin.__xpTabEventState = scwin.__xpTabEventState || {};
scwin.__xpTabBefore_tabMain = function(selectedIndex, index) { var obj=$p.getComponentById("tabMain"); scwin.__xpTabEventState["tabMain"] = selectedIndex; var e={preindex:selectedIndex,postindex:index,pretext:'',posttext:''}; try{if(obj&&obj.getLabelText){if(typeof selectedIndex==='number'&&selectedIndex>=0)e.pretext=obj.getLabelText(selectedIndex);if(typeof index==='number'&&index>=0)e.posttext=obj.getLabelText(index);}}catch(ignore){} var r=scwin.tabMain_canchange(e); return r===false?false:true; };
scwin.__xpTabChanged_tabMain = function(tabId, index, userTabId) { var obj=$p.getComponentById("tabMain"); var pre=scwin.__xpTabEventState["tabMain"]; var e={preindex:pre,postindex:index,pretext:'',posttext:'',tabid:tabId,userTabId:userTabId}; try{if(obj&&obj.getLabelText){if(typeof pre==='number'&&pre>=0)e.pretext=obj.getLabelText(pre);if(typeof index==='number'&&index>=0)e.posttext=obj.getLabelText(index);}}catch(ignore){} scwin.__xpTabEventState["tabMain"]=index; return scwin.tabMain_onchanged(e); };
